{# templates/upstream.conf.j2 #}
{{ ansible_managed | comment }}
upstream {{ app_name }} {
{% for host in groups['app'] %}
    server {{ hostvars[host]['ansible_host'] | default(host) }}:{{ app_port }};
{% endfor %}
}
server {
    listen 80;
    server_name {{ server_names | join(' ') }};
{% if enable_gzip | default(false) %}
    gzip on;
{% endif %}
    location / { proxy_pass http://{{ app_name }}; }
}
